head.b:skin:
/* ==========================================================
   Life in America — Blogger theme for oneofkind77.com
   Palette: cream paper, navy ink, sunset coral, road-line gold
   ========================================================== */
:root {
  --paper: #f8f4ec;
  --paper-2: #efe8db;
  --surface: #fffdf9;
  --ink: #14213d;
  --ink-2: #0f1a33;
  --text: #1c2233;
  --muted: #5f6676;
  --accent: #d9643a;
  --accent-2: #b94f2a;
  --gold: #ffcf7a;
  --red: #c8323c;
  --line: #e3dac9;
  --shadow: 0 22px 50px -26px rgba(20, 33, 61, 0.45);
  --serif: "Fraunces", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --header-h: 76px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --paper: #10141d;
    --paper-2: #161b26;
    --surface: #1c2230;
    --text: #ebe7df;
    --muted: #a2a8b5;
    --accent: #f08a5d;
    --accent-2: #f5a17b;
    --line: #2b3242;
    --shadow: 0 22px 50px -26px rgba(0, 0, 0, 0.75);
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; font: 400 1rem/1.7 var(--sans); background: var(--paper); color: var(--text); -webkit-font-smoothing: antialiased; }
h1, h2, h3, h4 { font-family: var(--serif); font-weight: 600; line-height: 1.12; letter-spacing: -0.015em; margin: 0 0 0.45em; }
h2 { font-size: clamp(2rem, 4.2vw, 3.1rem); }
h3 { font-size: 1.45rem; }
a { color: inherit; }
img { max-width: 100%; height: auto; }
.container { width: min(1180px, 100% - 40px); margin-inline: auto; }
.section { padding: clamp(72px, 10vw, 128px) 0; }
.section-paper { background: var(--paper-2); }
.section-head { margin-bottom: 44px; max-width: 720px; }
.section-lead { color: var(--muted); font-size: 1.08rem; margin: 0; }
.eyebrow { font-size: 0.74rem; font-weight: 600; letter-spacing: 0.2em; text-transform: uppercase; color: var(--accent); margin: 0 0 16px; display: flex; align-items: center; gap: 12px; }
.eyebrow::before { content: ""; width: 26px; height: 2px; background: currentColor; border-radius: 2px; flex-shrink: 0; }
.eyebrow a { text-decoration: none; }
.eyebrow.light { color: var(--gold); }
.small { font-size: 0.82rem; color: var(--muted); }
.sr-only, .skip-link { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip-link:focus { clip: auto; width: auto; height: auto; z-index: 100; top: 8px; left: 8px; padding: 10px 16px; background: var(--surface); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* Road-line stripe (echoes the road in the hero) */
.stripe { height: 10px; background: #1c2742 repeating-linear-gradient(90deg, var(--gold) 0 30px, transparent 30px 56px) 0 50% / 100% 2px no-repeat; }

/* Buttons */
.btn { display: inline-flex; align-items: center; gap: 8px; border: 1px solid transparent; cursor: pointer; background: var(--ink); color: #fff; padding: 14px 26px; border-radius: 999px; font: 500 0.95rem var(--sans); text-decoration: none; transition: background .25s, transform .25s, color .25s; }
.btn:hover { background: var(--accent); transform: translateY(-2px); }
.btn-light { background: #fffdf9; color: var(--ink); }
.btn-light:hover { background: var(--gold); color: var(--ink); }
.btn-outline-light { background: transparent; color: #fffdf9; border-color: rgba(255, 253, 249, 0.45); }
.btn-outline-light:hover { background: rgba(255, 253, 249, 0.1); border-color: #fffdf9; }
@media (prefers-color-scheme: dark) { .btn:not(.btn-light):not(.btn-outline-light) { background: var(--accent); color: #10141d; } }
.text-link { color: var(--accent); font-weight: 600; text-decoration: none; }
.text-link:hover { text-decoration: underline; }

/* ---------- Header ---------- */
.site-header { position: fixed; inset: 0 0 auto; z-index: 30; color: var(--text); background: color-mix(in srgb, var(--paper) 94%, transparent); backdrop-filter: blur(12px); box-shadow: 0 1px 0 var(--line); transition: background .3s, color .3s, box-shadow .3s; }
.is-home .site-header:not(.scrolled) { background: transparent; color: #fffdf9; box-shadow: none; backdrop-filter: none; }
main { display: block; padding-top: var(--header-h); }
.is-home main { padding-top: 0; }
.nav { display: flex; align-items: center; justify-content: space-between; gap: 24px; height: var(--header-h); }
.brand { display: flex; align-items: center; gap: 12px; text-decoration: none; color: inherit; min-width: 0; }
.brand-mark { display: inline-grid; place-content: center; width: 40px; height: 40px; flex-shrink: 0; border-radius: 10px; background: var(--ink); color: var(--gold); font-size: 1.2rem; box-shadow: inset 0 -4px 0 var(--accent); }
.brand-text { display: flex; flex-direction: column; line-height: 1.05; min-width: 0; }
.brand-kicker { font-size: 0.6rem; font-weight: 600; letter-spacing: 0.24em; text-transform: uppercase; opacity: .7; margin-bottom: 4px; }
.brand-name { font: 600 1.28rem var(--serif); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.nav-links { display: flex; align-items: center; gap: 22px; }
.nav-links .widget { margin: 0; }
.nav-links .widget > .title, .nav-links h3 { display: none; }
.nav-links ul { list-style: none; margin: 0; padding: 0; display: flex; gap: 26px; }
.nav-links li a { text-decoration: none; font-size: 0.92rem; font-weight: 500; opacity: .85; transition: opacity .2s; }
.nav-links li a:hover, .nav-links li.selected a { opacity: 1; }
.nav-search input { width: 170px; padding: 9px 16px; border-radius: 999px; border: 1px solid currentColor; background: transparent; color: inherit; font: 0.88rem var(--sans); opacity: .8; transition: width .3s, opacity .3s; }
.nav-search input::placeholder { color: inherit; opacity: .7; }
.nav-search input:focus { width: 220px; opacity: 1; outline: none; }
.nav-toggle { display: none; width: 40px; height: 40px; border: 0; background: none; color: inherit; cursor: pointer; flex-direction: column; justify-content: center; gap: 7px; }
.nav-toggle span { display: block; height: 1.5px; background: currentColor; transition: transform .3s; }
.nav-toggle[aria-expanded="true"] span:first-child { transform: translateY(4px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] span:last-child { transform: translateY(-4.5px) rotate(-45deg); }

/* ---------- Hero ---------- */
