.hero-content { position: relative; z-index: 2; padding: 130px 0 24vh; }
.hero h1 { font-size: clamp(3.1rem, 8vw, 6.6rem); font-weight: 500; line-height: .98; margin-bottom: 26px; }
.hero h1 em { color: var(--gold); font-style: italic; }
.lead { font-size: clamp(1.05rem, 1.6vw, 1.2rem); max-width: 34em; color: rgba(255,253,249,.85); margin: 0 0 38px; }
.hero-actions { display: flex; gap: 14px; flex-wrap: wrap; }
.scroll-cue { position: absolute; z-index: 2; left: 50%; bottom: 26px; width: 26px; height: 42px; border: 1.5px solid rgba(255,253,249,.55); border-radius: 20px; transform: translateX(-50%); }
.scroll-cue span { position: absolute; left: 50%; top: 8px; width: 3px; height: 8px; margin-left: -1.5px; border-radius: 2px; background: #fffdf9; animation: cue 1.8s ease-in-out infinite; }
@keyframes cue { 0% { opacity: 0; transform: translateY(0); } 40% { opacity: 1; } 100% { opacity: 0; transform: translateY(14px); } }

