.desert-bg::before { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(20,24,52,.55), rgba(20,24,52,.05) 45%, rgba(40,16,10,.25)); pointer-events: none; }
.desert-bg > .container { position: relative; }
.desert-bg .eyebrow { color: var(--gold); }
.desert-bg .section-lead { color: rgba(255,253,249,.82); }
.desert-bg h2 { text-shadow: 0 2px 20px rgba(0,0,0,.25); }

/* ---------- Posts on an Americana wallpaper ---------- */
