nsform=%22translate(300 190) rotate(0)%22%3E%3Ccircle r=%2222%22/%3E%3Cpath d=%22M-14 -17 C-6 -8 -6 8 -14 17 M14 -17 C6 -8 6 8 14 17%22/%3E%3Cpath d=%22M-12 -10 l-5 2 M-10 -3 l-5 1 M-10 4 l-5 -1 M12 -10 l5 2 M10 -3 l5 1 M10 4 l5 -1%22/%3E%3C/g%3E%3Cg transform=%22translate(70 290) rotate(-4)%22%3E%3Cpath d=%22M-32 10 C-20 20 20 20 32 10%22/%3E%3Cpath d=%22M-18 12 C-18 -4 -16 -18 -10 -18 C-6 -18 -4 -12 0 -12 C4 -12 6 -18 10 -18 C16 -18 18 -4 18 12%22/%3E%3Cpath d=%22M-18 4 C-6 8 6 8 18 4%22/%3E%3C/g%3E%3Cg transform=%22translate(190 290) rotate(5)%22%3E%3Crect x=%22-30%22 y=%22-16%22 width=%2260%22 height=%2230%22 rx=%225%22/%3E%3Cpath d=%22M-24 -10 h10 v10 h-10z M-8 -10 h10 v10 h-10z M8 -10 h10 v10 h-10z%22/%3E%3Ccircle cx=%22-18%22 cy=%2216%22 r=%225%22/%3E%3Ccircle cx=%2218%22 cy=%2216%22 r=%225%22/%3E%3C/g%3E%3Cg transform=%22translate(290 285) rotate(-12)%22%3E%3Cpath d=%22M0 -14 L4 -4 L14 -4 L6 3 L9 13 L0 7 L-9 13 L-6 3 L-14 -4 L-4 -4Z%22/%3E%3C/g%3E%3Cg transform=%22translate(120 245) rotate(0)%22%3E%3Cpath d=%22M0 -14 L4 -4 L14 -4 L6 3 L9 13 L0 7 L-9 13 L-6 3 L-14 -4 L-4 -4Z%22/%3E%3C/g%3E %3C/g%3E%3C/svg%3E") 0 0 / 340px 340px repeat; }
.is-single .posts-zone { background-image: none; }
@media (prefers-color-scheme: dark) { .posts-zone { background-image: none; } }
.latest-head { padding-top: clamp(64px, 9vw, 110px); }

/* ---------- Trading cards ---------- */
.guides, .post-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 34px 28px; }
.tcg {
  --c1: #e7dcc7; --c2: #a89a80; --rx: 0deg; --ry: 0deg; --mx: 50%; --my: 50%;
  position: relative; display: block; padding: 11px; border-radius: 20px; text-decoration: none; color: #1b1b1b;
  background: linear-gradient(145deg, #fbe98f, #e6b83c 28%, #fff3b0 52%, #d8a22e 78%, #f7e27a);
  box-shadow: 0 1px 0 rgba(255,255,255,.6) inset, 0 18px 40px -18px rgba(20,33,61,.55), 0 4px 10px -4px rgba(20,33,61,.3);
  transform: perspective(900px) rotateX(var(--rx)) rotateY(var(--ry));
  transform-style: preserve-3d; transition: transform .5s cubic-bezier(.2,.7,.2,1), box-shadow .4s;
}
.tcg.tilting { transition: transform .08s linear, box-shadow .4s; }
.tcg:hover { box-shadow: 0 1px 0 rgba(255,255,255,.6) inset, 0 34px 60px -22px rgba(20,33,61,.7), 0 6px 14px -6px rgba(20,33,61,.35); }
.tcg-inner {
  position: relative; height: 100%; display: flex; flex-direction: column; gap: 8px; padding: 10px 12px 12px; border-radius: 11px; overflow: hidden;
  background: repeating-linear-gradient(135deg, rgba(255,255,255,.14) 0 2px, transparent 2px 7px), linear-gradient(170deg, var(--c1), var(--c2));
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.18);
}
.tcg-top { display: flex; justify-content: space-between; align-items: center; font-size: .64rem; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; }
.tcg-stage { padding: 2px 9px; border-radius: 999px; background: linear-gradient(180deg, #f4f4f4, #bdbdbd); border: 1px solid rgba(0,0,0,.25); font-style: italic; }
.tcg-no { opacity: .7; }
.tcg-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.tcg-name { margin: 0; font: 700 1.28rem/1.15 var(--serif); letter-spacing: -.01em; color: #151515; }
.tcg-name a { text-decoration: none; color: inherit; }
.post-grid .tcg-name { font-size: 1.12rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.tcg-hp { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; font: 800 1.2rem/1 var(--sans); color: #b3261e; }
.tcg-hp small { font-size: .6rem; font-weight: 700; color: #1b1b1b; }
.energy, .cost i { display: inline-block; width: 20px; height: 20px; border-radius: 50%; flex-shrink: 0;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.85), rgba(255,255,255,0) 45%), var(--c2);
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.7), 0 1px 2px rgba(0,0,0,.35); }
.tcg-art { display: block; padding: 4px; border-radius: 4px; background: linear-gradient(135deg, #fff7c2, #b88a22 30%, #fff3b0 55%, #b88a22 80%, #fff7c2); box-shadow: 0 2px 6px rgba(0,0,0,.3); }
.tcg-art-in { position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; overflow: hidden; border-radius: 2px;
  background: repeating-conic-gradient(from 0deg at 50% 62%, rgba(255,255,255,.22) 0 9deg, transparent 9deg 18deg), radial-gradient(circle at 50% 62%, #fffbe8 0, var(--c1) 38%, var(--c2) 100%); }
.tcg-art-in img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.tcg-art-in svg { width: 46%; height: auto; fill: none; stroke: #fff; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 3px 0 rgba(0,0,0,.25)) drop-shadow(0 8px 14px rgba(0,0,0,.25)); }
.tcg-art-star { font-size: 3.4rem; color: #fff; text-shadow: 0 3px 0 rgba(0,0,0,.2); }
.tcg-strip { margin: -2px 10px 0; padding: 3px 10px; text-align: center; font-size: .68rem; font-style: italic; font-weight: 500; border-radius: 3px;
  background: linear-gradient(90deg, #c9a13a, #fff0a8 30%, #fff0a8 70%, #c9a13a); box-shadow: 0 1px 2px rgba(0,0,0,.25); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tcg-strip a { color: inherit; text-decoration: none; font-weight: 700; }
.tcg-move { display: grid; grid-template-columns: auto 1fr auto; align-items: start; gap: 10px; padding: 7px 2px; border-bottom: 1px solid rgba(0,0,0,.16); }
.tcg-move .cost { display: flex; gap: 3px; padding-top: 2px; min-width: 20px; }
.tcg-move .cost i { width: 17px; height: 17px; }
.tcg-move b { display: block; font: 700 .98rem/1.2 var(--sans); }
.tcg-move p, .tcg-text { margin: 2px 0 0; font-size: .8rem; line-height: 1.45; color: #2a2a2a; }
.post-grid .tcg-text { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin: 0; }
.tcg-dmg { font: 800 1.1rem/1 var(--sans); padding-top: 2px; }
.tcg-foot { margin-top: auto; display: flex; justify-content: space-between; align-items: center; gap: 8px; padding-top: 6px; font-size: .64rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.tcg-foot span { opacity: .8; }
.tcg-read { font-size: .78rem; letter-spacing: .04em; text-decoration: none; color: #151515; border-bottom: 2px solid rgba(0,0,0,.35); }
.tcg-read:hover { border-color: #151515; }
.tcg-rarity { font-size: .8rem; opacity: .75; }
.tcg-flavor { margin: 0; padding: 6px 8px; font: italic 500 .74rem/1.4 var(--serif); border: 1px solid rgba(0,0,0,.25); border-radius: 3px; background: rgba(255,255,255,.28); }

/* Holographic shine + glare, driven by --mx / --my from script.js */
.tcg-shine { position: absolute; inset: 0; border-radius: 20px; pointer-events: none; opacity: 0; transition: opacity .35s; mix-blend-mode: color-dodge;
  background: radial-gradient(circle at var(--mx) var(--my), rgba(255,255,255,.55), transparent 42%),
    linear-gradient(115deg, transparent 18%, rgba(255,0,170,.38) 32%, rgba(0,240,255,.38) 44%, rgba(255,245,0,.38) 56%, rgba(120,255,120,.3) 66%, transparent 80%);
  background-size: 100% 100%, 250% 250%; background-position: center, var(--mx) var(--my); }
.tcg:hover .tcg-shine, .tcg:focus-within .tcg-shine { opacity: .6; }
@media (prefers-reduced-motion: reduce) { .tcg { transform: none !important; } }

/* Energy types */
.t-grass     { --c1: #cfeaa0; --c2: #62a53f; }
.t-lightning { --c1: #fff0a0; --c2: #e0a92b; }
.t-water     { --c1: #bfe4f6; --c2: #3f86c2; }
.t-fire      { --c1: #fbc39e; --c2: #d9482b; }
.t-steel     { --c1: #e1e6ec; --c2: #7d8a9c; }
.t-psychic   { --c1: #efcdf6; --c2: #9a58b5; }
.t-earth     { --c1: #f1d2a4; --c2: #b06a35; }

/* ---------- List pages ---------- */
.main-wrap { padding-bottom: clamp(64px, 9vw, 110px); }
.is-home .main-wrap { padding-top: 0; }
.list-head { padding: clamp(48px, 7vw, 90px) 0 36px; }
.list-head h1 { font-size: clamp(2.3rem, 5.5vw, 3.8rem); margin: 0; }


/* Pagination (Blogger default markup) */
.blog-pager, #blog-pager { display: flex; justify-content: center; gap: 12px; flex-wrap: wrap; margin: 56px 0 0; }
.blog-pager a, #blog-pager a { display: inline-flex; align-items: center; padding: 12px 24px; border: 1px solid var(--line); border-radius: 999px; text-decoration: none; font-weight: 500; font-size: 0.92rem; transition: all .2s; }
.blog-pager a:hover, #blog-pager a:hover { border-color: var(--accent); color: var(--accent); }
.blog-pager svg, #blog-pager svg { display: none; }

/* ---------- Single post / page ---------- */
.post-single { max-width: 760px; margin: 0 auto; }
.post-hero { padding: clamp(48px, 7vw, 96px) 0 34px; }
.post-title { font-size: clamp(2.3rem, 5.5vw, 3.9rem); margin: 0; }
.post-meta { margin: 18px 0 0; color: var(--muted); font-size: 0.92rem; }
.post-single .stripe { margin-bottom: clamp(36px, 5vw, 56px); border-radius: 2px; }
.post-body { font-size: 1.1rem; line-height: 1.82; overflow-wrap: break-word; }
.post-body > * { margin-top: 0; }
.post-body p { margin: 0 0 1.35em; }
.post-body h2 { font-size: clamp(1.7rem, 3.3vw, 2.2rem); margin: 1.8em 0 0.6em; }
.post-body h3 { font-size: 1.45rem; margin: 1.6em 0 0.5em; }
.post-body h4 { font-size: 1.2rem; margin: 1.4em 0 0.4em; }
.post-body a { color: var(--accent-2); text-underline-offset: 3px; }
@media (prefers-color-scheme: dark) { .post-body a { color: var(--accent); } }
.post-body ul, .post-body ol { padding-left: 1.3em; margin: 0 0 1.4em; }
.post-body li { margin-bottom: 0.45em; }
.post-body li::marker { color: var(--accent); }
.post-body blockquote { margin: 1.8em 0; padding: 18px 26px; border-left: 4px solid var(--accent); background: var(--surface); border-radius: 0 12px 12px 0; font: italic 500 1.3rem/1.55 var(--serif); }
.post-body img { border-radius: 12px; height: auto !important; }
.post-body .separator a { margin-left: 0 !important; margin-right: 0 !important; }
.post-body .tr-caption-container { margin: 1.5em auto; }
.post-body .tr-caption { font-size: 0.85rem; color: var(--muted); padding-top: 8px; }
.post-body table:not(.tr-caption-container) { width: 100%; border-collapse: collapse; font-size: 0.98rem; margin: 0 0 1.6em; }
.post-body table:not(.tr-caption-container) th, .post-body table:not(.tr-caption-container) td { border-bottom: 1px solid var(--line); padding: 10px 12px; text-align: left; }
.post-body hr { border: 0; height: 2px; margin: 3em 0; background-image: repeating-linear-gradient(90deg, var(--accent) 0 30px, transparent 30px 56px); }
.post-body pre, .post-body code { font-family: ui-monospace, Menlo, monospace; font-size: 0.9em; background: var(--paper-2); border-radius: 6px; }
.post-body code { padding: 2px 6px; }
.post-body pre { padding: 16px 18px; overflow-x: auto; }
.post-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 44px 0 0; }
.post-tags a { font-size: 0.85rem; text-decoration: none; color: var(--muted); border: 1px solid var(--line); padding: 5px 13px; border-radius: 999px; }
.post-tags a:hover { color: var(--accent); border-color: var(--accent); }
.is-single #blog-pager, .is-single .blog-pager { max-width: 760px; margin-inline: auto; justify-content: space-between; }

/* Comments (Blogger default markup) */
.comments { max-width: 760px; margin: 64px auto 0; padding-top: 40px; border-top: 1px solid var(--line); }
.comments .title, .comments h3 { font: 600 1.6rem var(--serif); margin-bottom: 20px; }
.comments .comment-thread ol { list-style: none; padding: 0; margin: 0; }
.comments .comment-thread .thread-inline, .comments .comment-replies { padding-left: 28px; }
.comments .comment { padding: 18px 0; border-bottom: 1px solid var(--line); }
.comments .comment-header .user, .comments .comment-header .user a { font-weight: 600; text-decoration: none; }
.comments .datetime, .comments .datetime a { font-size: 0.8rem; color: var(--muted); text-decoration: none; margin-left: 8px; }
.comments .comment-content { margin: 8px 0; }
.comments .comment-actions a, .comments .comment-footer a { font-size: 0.85rem; color: var(--accent); text-decoration: none; margin-right: 12px; }
.comments .avatar-image-container { display: none; }
.comments iframe { width: 100%; border: 0; }
.comments .comment-replybox-single, .comments .comment-form { margin-top: 20px; }

/* Empty / 404 */
.empty-state { max-width: 640px; margin: 0 auto; padding: clamp(64px, 10vw, 130px) 0; text-align: center; }
.empty-state .eyebrow { justify-content: center; }
.empty-state h1 { font-size: clamp(2.3rem, 6vw, 3.6rem); }
.empty-state p { color: var(--muted); }
.small-empty { padding: 40px 0; }
.search-box { display: flex; gap: 8px; margin: 28px auto; padding: 6px; max-width: 560px; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); }
.search-box input { flex: 1; min-width: 0; padding: 10px 18px; border: 0; background: transparent; color: var(--text); font: 1rem var(--sans); outline: none; }

/* Ad slot */
.ad-slot .widget { margin: 48px auto 0; max-width: 760px; text-align: center; }
.ad-slot .widget > .title, .ad-slot h3 { display: none; }

/* ---------- Topics & popular (home only) ---------- */
.home-only { display: none; }
.is-home .home-only { display: block; }
.topics-grid { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(40px, 6vw, 90px); }
.topics-grid .widget { margin: 0; }
.topics-grid .widget > .title, .topics-grid h3.title { font: 600 clamp(1.8rem, 3.4vw, 2.4rem) var(--serif); margin: 0 0 26px; }
.Label ul { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
.Label li a, .Label .label-name { display: inline-flex; align-items: center; gap: 8px; padding: 10px 18px; background: var(--surface); border: 1px solid var(--line); border-radius: 999px; text-decoration: none; font-weight: 500; font-size: 0.95rem; transition: all .2s; }
.Label li a:hover { border-color: var(--accent); color: var(--accent); }
.Label .label-count { font-size: 0.78rem; color: var(--muted); }
.Label .show-more, .Label .remaining-items { display: none; }
.PopularPosts [role="feed"], .PopularPosts .widget-content { display: grid; gap: 14px; }
.PopularPosts article, .PopularPosts .post { margin: 0; padding: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; }
.PopularPosts .post-content { display: flex; gap: 16px; align-items: center; }
.PopularPosts img, .PopularPosts .post-thumb { width: 92px; height: 68px; object-fit: cover; border-radius: 10px; flex-shrink: 0; }
.PopularPosts .post-title { font: 600 1.12rem/1.3 var(--serif); margin: 0; }
.PopularPosts .post-title a { text-decoration: none; }
.PopularPosts .post-title a:hover { color: var(--accent); }
.PopularPosts .post-header, .PopularPosts .item-byline, .PopularPosts .snippet-item, .PopularPosts .jump-link, .PopularPosts .post-footer { display: none; }

/* ---------- CTA ---------- */
.cta-wrap { padding: clamp(80px, 10vw, 130px) 0; text-align: center; }
.cta { max-width: 680px; }
.cta p { color: var(--muted); }

/* ---------- Footer ---------- */
.site-footer { background: var(--ink-2); color: #fffdf9; }
.footer-inner { padding: 56px 0 40px; display: grid; justify-items: center; gap: 16px; text-align: center; }
.footer-tagline { margin: 0; font: italic 500 1.12rem var(--serif); color: rgba(255,253,249,.72); }
.footer-links .widget { margin: 0; }
.footer-links .widget > .title, .footer-links h3 { display: none; }
.footer-links ul { list-style: none; margin: 8px 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 26px; }
.footer-links a { color: rgba(255,253,249,.75); text-decoration: none; font-size: 0.9rem; }
.footer-links a:hover { color: #fff; }
.site-footer .small { color: rgba(255,253,249,.5); margin: 0; }

/* ---------- Scroll reveal ---------- */
.js .reveal { opacity: 0; transform: translateY(26px); transition: opacity .8s ease, transform .8s cubic-bezier(.2,.7,.2,1); }
.js .reveal.in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .js .reveal { opacity: 1; transform: none; transition: none; }
  .scroll-cue span { animation: none; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1040px) {
  .guides, .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .nav-search input { width: 140px; }
}
@media (max-width: 900px) {
  .nav-toggle { display: flex; }
  .nav-links { position: fixed; top: var(--header-h); left: 0; right: 0; flex-direction: column; align-items: stretch; gap: 20px; padding: 26px 22px 30px; background: var(--paper); color: var(--text); box-shadow: 0 20px 30px -20px rgba(0,0,0,.3); transform: translateY(-12px); opacity: 0; pointer-events: none; transition: all .25s; }
  .nav-links.open { transform: none; opacity: 1; pointer-events: auto; }
  .nav-links ul { flex-direction: column; gap: 18px; }
  .nav-links li a { font-size: 1.05rem; }
  .nav-search input, .nav-search input:focus { width: 100%; }
  .topics-grid { grid-template-columns: 1fr; }
